CREATE TABLE IF NOT EXISTS inv_issues (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, issue_ref VARCHAR(80) NOT NULL UNIQUE, issue_date DATE NOT NULL, branch_id INT UNSIGNED NOT NULL, recipient VARCHAR(160) NULL, document_ref VARCHAR(100) NULL, note VARCHAR(255) NULL, status ENUM('DRAFT','POSTED') NOT NULL DEFAULT 'DRAFT', created_by INT UNSIGNED NOT NULL, created_at DATETIME NOT NULL, posted_by INT UNSIGNED NULL, posted_at DATETIME NULL, CONSTRAINT fk_inv_issue_branch FOREIGN KEY(branch_id) REFERENCES branches(id), KEY ix_inv_issue_scope(branch_id,issue_date,status)); CREATE TABLE IF NOT EXISTS inv_issue_lines (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, issue_id INT UNSIGNED NOT NULL, item_id INT UNSIGNED NOT NULL, quantity DECIMAL(18,3) NOT NULL, created_at DATETIME NOT NULL, CONSTRAINT fk_inv_issue_header FOREIGN KEY(issue_id) REFERENCES inv_issues(id) ON DELETE CASCADE, CONSTRAINT fk_inv_issue_item FOREIGN KEY(item_id) REFERENCES md_items(id), CHECK(quantity>0)); INSERT IGNORE INTO permissions(code,name) VALUES ('inventory.issue.view','Lihat barang keluar'),('inventory.issue.create','Buat barang keluar'),('inventory.issue.post','Posting barang keluar'); INSERT IGNORE INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON p.code='inventory.issue.view' WHERE r.name IN ('Owner','Finance');